1945	    State((state, template)): State<(Arc<service_v2::State>, Option<RequestTemplate>)>,
1946	    headers: HeaderMap,
1947	    body: Body,
1948	) -> Result<Response, ErrorResponse> {
1949	    let body = read_json_request_body(&headers, body).await?;
1950	    let mut request: NvCreateChatCompletionRequest = parse_json_request("chat completions", &body)?;
1951	    if *FORCE_INCLUDE_USAGE && request.inner.stream.unwrap_or(false) {
1952	        delta_common::force_include_usage(&mut request.inner.stream_options);
1953	    }
1954	
